// The ".NET Under the Hood" track.
//
// Content is original teaching material. Book references point at Jeffrey Richter,
// "CLR via C#, Fourth Edition" (Microsoft Press, 2012); chapter and section titles
// were taken from the publisher's table of contents. Documentation links point at
// current Microsoft Learn pages. No book text is reproduced here.

public record ModuleDoc(string Title, string Url);

public record ModuleSection(string Title, int Minutes, string Body, string Code = "");

public record Module(
    string Id,
    string Title,
    string Summary,
    string Outcome,
    int Minutes,
    string TsComparison,
    string BookReference,
    ModuleDoc[] Docs,
    ModuleSection[] Sections,
    string AppliesToday,
    string Historical,
    string Checkpoint,
    string GenerationFocus,
    Question[] Questions);

public static class Curriculum {
    public static readonly string[] ReviewCriteria = [
        "I distinguished copying a struct value from copying a class reference.",
        "I explained why property mutation reaches the caller but parameter reassignment does not.",
        "I compared TypeScript object references and noted that copying is not necessarily a deep clone.",
        "I explained that boxing copies a value type into a heap object and that the box is a separate copy."
    ];

    // The four questions that established the original learning lab. They remain the
    // foundation set so existing Markdown progress keeps working unchanged.
    public static readonly Question[] Questions = [
        new("copy", "multiple-choice", "What does assigning one C# class variable to another copy?", "var first = new Person { Name = \"Ada\" };\nvar second = first;", ["The entire object", "A reference to the same object", "An immutable snapshot"], "A reference to the same object", "Assignment copies the reference. Both variables refer to the same Person object. Mutating its Name through either variable is visible through both; reassigning one variable does not reassign the other.", "Separate the variable from the object it refers to.", "Like const second = first for a TypeScript object. const restricts reassignment, not mutation."),
        new("struct", "prediction", "Predict the output when a struct is copied.", "var a = new Counter { Value = 1 };\nvar b = a;\nb.Value = 7;\nConsole.WriteLine(a.Value);\nstruct Counter { public int Value; }", ["1", "7", "It does not compile"], "1", "Counter is a struct, so assignment copies its value. Changing b.Value does not change a.Value. Structs can still contain reference fields, so a value copy is not always a deep clone.", "Counter is declared as a struct, not a class.", "TypeScript object assignment shares an object. A C# struct has value semantics; spreading an object is only a rough shallow-copy comparison."),
        new("parameter", "bug", "Why does this method fail to replace the caller's person?", "void Replace(Person person) {\n  person = new Person { Name = \"Grace\" };\n}\nvar original = new Person { Name = \"Ada\" };\nReplace(original);", ["Classes cannot be method arguments", "The reference is passed by value", "The garbage collector restores Ada"], "The reference is passed by value", "The method receives a copy of the reference. Reassigning its local parameter does not change original. Mutating person.Name would affect the shared object. Return the replacement and assign it at the call site, or deliberately use ref when appropriate.", "Would mutating a property behave differently from replacing the local variable?", "Node.js behaves similarly: reassigning a function parameter does not replace the caller's object variable."),
        new("explain", "explanation", "Explain copied values versus copied references, and what changes when a value type is boxed. Distinguish property mutation from parameter reassignment, and compare with TypeScript.", "void Rename(Person p) { p.Name = \"Grace\"; }\nvoid Replace(Person p) { p = new Person(); }\nobject boxed = new Counter { Value = 1 };", [], "", "Struct assignment copies the value; class assignment copies a reference to the same object. Ordinary parameters are passed by value, including references. Rename mutates the shared object and is visible to the caller; Replace reassigns only the local parameter. Boxing copies a value type into a heap object, so mutating the original afterwards does not change the box, and unboxing copies the value back out. TypeScript objects share references similarly, but TypeScript has no user-defined value types and no boxing. Neither class assignment nor struct assignment guarantees a deep copy; a struct can contain reference fields.", "Explain separately what is copied, what is mutated, which variable is reassigned, and what the box holds.", "Compare these methods to an Angular service mutating a shared model versus assigning its parameter to a new object, and compare boxing to wrapping a primitive in an object."),
    ];

    public static readonly Module[] Modules = BuildModules();

    // Direct links to the referenced chapters, so a learner can read the source.
    static readonly Dictionary<string, string> ChapterLinks = new() {
        ["value-types"] = "https://www.oreilly.com/library/view/clr-via-c/9780735668737/ch05.html",
        ["clr"] = "https://www.oreilly.com/library/view/clr-via-c/9780735668737/ch01.html",
        ["gc"] = "https://www.oreilly.com/library/view/clr-via-c/9780735668737/ch21.html",
        ["dispose"] = "https://www.oreilly.com/library/view/clr-via-c/9780735668737/ch21.html",
        ["async"] = "https://www.oreilly.com/library/view/clr-via-c/9780735668737/ch28.html",
        ["generics"] = "https://www.oreilly.com/library/view/clr-via-c/9780735668737/ch12.html",
        ["exceptions"] = "https://www.oreilly.com/library/view/clr-via-c/9780735668737/ch20.html",
        ["reflection"] = "https://www.oreilly.com/library/view/clr-via-c/9780735668737/ch23.html"
    };

    public static string BookUrl(string moduleId) => ChapterLinks.GetValueOrDefault(moduleId, "https://www.oreilly.com/library/view/clr-via-c/9780735668737/");

    public static Module Find(string id) => Modules.FirstOrDefault(m => m.Id == id) ?? Modules[0];

    static Module[] BuildModules() => [
        new Module(
            "value-types",
            "Value Types, Reference Types and Boxing",
            "Predict what a C# assignment copies, when a value type is boxed, and why mutation surprises appear in services and background workers.",
            "Explain what is copied on assignment, recognise hidden boxing on hot paths, and predict mutation and equality behaviour.",
            22,
            "TypeScript has primitives like number and string, and reference values like objects and arrays. Assigning an object copies the reference, so both variables point at the same object, and const only stops you reassigning the variable. C# splits types differently. A class is a reference type. A struct, enum, record struct or primitive is a value type, and assignment copies the value. TypeScript has no value types you can define, and no boxing.",
            "CLR via C#, 4th Edition - Chapter 5, \"Primitive, Reference, and Value Types\" (sections \"Reference Types and Value Types\", \"Boxing and Unboxing Value Types\", \"Object Equality and Identity\").",
            [
                new("Value types (C# reference)", "https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/builtin-types/value-types"),
                new("Reference types (C# reference)", "https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/builtin-types/reference-types"),
                new("Boxing and unboxing (C# programming guide)", "https://learn.microsoft.com/en-us/dotnet/csharp/programming-guide/types/boxing-and-unboxing"),
                new("Structure types (C# reference)", "https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/builtin-types/struct")
            ],
            [
                new("Assignment copies a value or a reference", 7, "A reference type variable holds a pointer to an object on the heap. A value type variable holds the value itself. When you assign one class variable to another, you copy the pointer, so both names refer to the same object. When you assign one struct to another, you copy every field, so the two variables are independent.\n\nParameters work the same way. A class parameter receives a copy of the pointer; a struct parameter receives a copy of the whole value. Reassigning a parameter never changes the caller's variable. Changing a property of a shared object does.\n\nA struct copy is shallow. If the struct holds a reference field, such as a string or an array, both copies share that object.", "var a = new Counter { Value = 1 };   // struct\nvar b = a;\nb.Value = 7;\nConsole.WriteLine(a.Value);          // 1\n\nvar first = new Person { Name = \"Ada\" };  // class\nvar second = first;\nsecond.Name = \"Grace\";\nConsole.WriteLine(first.Name);       // Grace"),
                new("Boxing puts a value type in an object", 7, "Boxing happens when a value type has to be treated as object, or as an interface it implements. The runtime creates an object on the heap and copies the value into it. Unboxing copies the value back out. The box is a separate copy. If you change the original afterwards, the box does not change, and a cast does not let you change the box in place.\n\nYou will see boxing with non-generic collections such as ArrayList, with object parameters, and with interfaces implemented by structs. Every box is a heap allocation, so it adds work for the garbage collector. On a busy request path that adds up. Generic collections avoid it.", "struct Counter { public int Value; }\n\nvar c = new Counter { Value = 1 };\nobject boxed = c;\nc.Value = 7;\nConsole.WriteLine(((Counter)boxed).Value);  // 1\n\nvar list = new List<Counter>();  // no boxing"),
                new("Equality, identity and mutation", 6, "ReferenceEquals asks whether two variables point at the same object. The == operator and Equals depend on the type. Classes use reference equality by default. string, records and many framework types override it to compare values. A struct that does not override Equals and GetHashCode compares its fields by default.\n\nMutable structs cause quiet bugs. If you copy one by accident, a change can disappear. If you use one as a dictionary key, changing a field changes its hash and the key can no longer be found. Prefer readonly struct or record struct for data you pass around.", "var x = new Person { Name = \"Ada\" };\nvar y = new Person { Name = \"Ada\" };\nConsole.WriteLine(x == y);              // False: same data, different objects\n\nvar p = new Point(1, 2);\nvar q = new Point(1, 2);\nConsole.WriteLine(p == q);              // True: record struct value equality")
            ],
            "Value and reference behaviour is the same on .NET 10. Structs are copied on assignment, boxing still allocates, and readonly struct, ref struct, record struct and the Equals/GetHashCode rules all still apply. Nullable<T> has one special rule: a nullable with a value boxes the value, and a null nullable boxes to a null reference. Use generic collections to avoid boxing.",
            "On .NET Framework, ValueType.Equals used reflection and was slow, so overriding Equals and GetHashCode on structs was essential. The modern runtime optimises simple cases, but overriding is still the safe choice. Do not copy .NET Framework-only features such as Thread.Abort or AppDomains into new code. Boxing itself has not changed.",
            "Good 8-minute stop: read sections 1 and 2, then answer the copy, struct and boxing questions. Come back later for equality and the code review.",
            "value types vs reference types, struct copy semantics, pass-by-value parameters, boxing and unboxing, mutation of a boxed copy, equality and identity. Use realistic service, API and background-worker scenarios.",
            Questions.Concat([
                new Question("boxing", "multiple-choice", "What happens when a struct is assigned to an object variable?", "struct Counter { public int Value; }\nvar c = new Counter { Value = 1 };\nobject boxed = c;\nc.Value = 7;\nConsole.WriteLine(((Counter)boxed).Value);", ["The struct is copied into a new heap object; the box still holds 1", "The object variable points at the struct on the stack, so it prints 7", "It does not compile because structs cannot be boxed"], "The struct is copied into a new heap object; the box still holds 1", "Assigning a value type to object or to an implemented interface boxes it: the runtime allocates an object on the managed heap and copies the value in. The box is independent of the original, so c.Value = 7 does not change it, and the unboxing cast copies 1 back out. Boxing allocates and adds GC pressure, so generic collections are preferred on hot paths.", "The word 'copy' is doing a lot of work here. What is copied, and where does it live?", "TypeScript has no boxing: primitives are not objects. Wrapping a primitive in an object is the closest analogue, and it is almost always unnecessary in both languages."),
                new Question("boxed-copy", "bug", "An AI assistant wrote this counter and claimed it prints 7. What actually happens?", "var list = new ArrayList();\nvar c = new Counter { Value = 1 };\nlist.Add(c);\nc.Value = 7;\nConsole.WriteLine(((Counter)list[0]).Value);\nstruct Counter { public int Value; }", ["It prints 1 because list.Add boxed a copy", "It prints 7 because the list stores a reference to c", "It does not compile because ArrayList is obsolete"], "It prints 1 because list.Add boxed a copy", "ArrayList.Add takes object, so the struct is boxed: a copy is placed on the heap. Mutating c afterwards changes the original, not the boxed copy, so the cast reads 1. Replacing ArrayList with List<Counter> removes the boxing and makes the intent explicit, though the copy semantics of structs still apply.", "Track the value from c into the collection. Which copy does the collection hold?", "A TypeScript array stores the same object reference, so mutating the original would be visible. C# value types behave differently as soon as they are boxed.")
            ]).ToArray()),

        new Module(
            "clr",
            "CLR, IL and JIT Compilation",
            "Understand what a build actually produces, why the first seconds of a service are slower, and what ahead-of-time compilation changes.",
            "Describe the path from C# to IL to native code and choose sensibly between JIT, ReadyToRun and Native AOT.",
            20,
            "Node runs JavaScript on V8, which compiles it to machine code while the program runs. TypeScript types are erased at build time, so nothing about them survives into JavaScript. C# keeps type information in the assembly as metadata, and the runtime uses it for the JIT, reflection and tooling.",
            "CLR via C#, 4th Edition - Chapter 1, \"The CLR's Execution Model\" (sections \"Compiling Source Code into Managed Modules\", \"Executing Your Assembly's Code\", \"IL and Verification\", \"The Native Code Generator Tool: NGen.exe\").",
            [
                new("Managed execution process", "https://learn.microsoft.com/en-us/dotnet/standard/managed-execution-process"),
                new("Managed code", "https://learn.microsoft.com/en-us/dotnet/standard/managed-code"),
                new("Common Language Runtime (CLR)", "https://learn.microsoft.com/en-us/dotnet/standard/clr"),
                new("Compilation config settings", "https://learn.microsoft.com/en-us/dotnet/core/runtime-config/compilation"),
                new("ReadyToRun compilation", "https://learn.microsoft.com/en-us/dotnet/core/deploying/ready-to-run"),
                new("What's new in the .NET 10 runtime", "https://learn.microsoft.com/en-us/dotnet/core/whats-new/dotnet-10/runtime")
            ],
            [
                new("From C# to IL to machine code", 7, "The C# compiler does not produce machine code. It produces a managed module: IL (a simple, typed instruction set), metadata that describes every type and member, and a manifest. When the program runs, the CLR loads the module, checks the IL, and the JIT compiles each method to machine code the first time it is called. dotnet build stops at IL. Publishing with ReadyToRun or Native AOT is what adds machine code ahead of time. Metadata is why reflection, debugging and tooling work.", "public static int Add(int a, int b) => a + b;\n// csc emits Add.dll: IL, metadata and a manifest - not machine code"),
                new("Tiered compilation and warm-up", 7, "The JIT has two jobs: start fast and run fast. It starts by compiling methods quickly with little optimisation (tier 0). It counts how often each method runs. Hot methods are compiled again in the background with full optimisation (tier 1). Dynamic PGO goes further: the runtime watches which branches and virtual calls actually happen, then feeds that profile to the optimising JIT so it can inline and devirtualise. This is why the first seconds of a service are slower than steady state, and why benchmarks need a warm-up.", "app.MapGet(\"/orders/{id}\", (int id) => repo.Find(id));\n// first calls run tier-0 code; hot methods are re-jitted"),
                new("ReadyToRun, Native AOT and trimming", 6, "ReadyToRun compiles IL to machine code ahead of time but keeps the IL as a fallback, so startup is faster and the JIT can still optimise hot paths. Native AOT compiles the whole app to machine code with no JIT: very fast startup and small memory, but no dynamic code generation and limited reflection. The trimmer removes code that nothing references. Both are publishing choices, not language changes.", "dotnet publish -c Release -p:PublishReadyToRun=true\ndotnet publish -c Release -p:PublishAot=true")
            ],
            "IL, metadata and JIT compilation are still the model on .NET 10. Tiered compilation has been on by default since .NET Core 3.0, and dynamic PGO is on by default in current .NET. ReadyToRun and Native AOT are the supported ahead-of-time options. .NET 10 keeps improving the JIT (inlining, devirtualisation, loop inversion, struct arguments) without code changes.",
            "NGen.exe and its machine-wide native image cache are gone. crossgen2/ReadyToRun and Native AOT replace it. .NET Framework had one machine-wide CLR with side-by-side versions and the GAC; a modern .NET app carries its own runtime. AppDomains, Thread.Abort and remoting do not exist, so designs that swapped in a new AppDomain do not port.",
            "Read section 1 and answer the IL and tiering questions, then stop (about 7 minutes). Tiered compilation and AOT are the second sitting.",
            "IL and metadata, JIT versus ahead-of-time compilation, tiered compilation and warm-up, ReadyToRun, Native AOT, trimming and reflection limits. Use service startup and deployment scenarios.",
            [
                new("clr-emit", "multiple-choice", "What does the C# compiler put in a built assembly?", "public static int Add(int a, int b) => a + b;", ["IL plus metadata and a manifest", "Native machine code for the target CPU", "JavaScript that the runtime interprets"], "IL plus metadata and a manifest", "csc emits IL, metadata for every type and member, and a manifest. The JIT turns IL into native code at run time. Publishing with ReadyToRun or Native AOT is what adds native code ahead of time; a normal build does not.", "Look at what the SDK produces by default, and what only appears when you pass a publishing option.", "TypeScript emits JavaScript that V8 compiles at run time. The C# compiler emits IL that the CLR compiles at run time, with metadata retained."),
                new("clr-tiered", "prediction", "A service handles its first requests slowly, then speeds up. Which explanation fits?", "static decimal Score(Order order) {\n  // hot method, called for every request\n  return order.Total * 1.2m;\n}", ["Tier-0 code runs first; hot methods are re-jitted to optimised code in the background", "The JIT compiles every method at startup, so the first call is already optimal", "The runtime interprets IL forever and never compiles it"], "Tier-0 code runs first; hot methods are re-jitted to optimised code in the background", "Tiered compilation starts with quickly-jitted tier-0 code, then re-jits hot methods. Dynamic PGO collects profiles from tier-0 and feeds them to the optimising JIT, so steady-state performance is better than startup performance. Benchmark after warm-up and expect container cold starts to pay this cost.", "Think about when the optimising JIT has enough evidence to make good decisions.", "V8 has a similar warm-up curve: interpreted or baseline code first, optimised code once a function is hot."),
                new("clr-aot", "bug", "An AI assistant generated this plugin loader. It passes tests under dotnet run but fails after dotnet publish -p:PublishAot=true. Why?", "var type = Type.GetType(\"MyApp.Handlers.OrderHandler\");\nvar handler = (IHandler)Activator.CreateInstance(type!)!;\nhandler.Handle(message);", ["Native AOT trims unreferenced types, so the string-named type may not exist at run time", "Native AOT forbids interfaces", "The code needs async to run under AOT"], "Native AOT trims unreferenced types, so the string-named type may not exist at run time", "The trimmer cannot see a type referenced only by a string. Under trimming or Native AOT that type can be removed, so Type.GetType returns null and Activator.CreateInstance throws. Annotate the target with DynamicallyAccessedMembers, keep a static reference, or replace the string lookup with a source-generated registration.", "Which parts of the app can the trimmer prove are used?", "Node has no trimming step by default, so a dynamic require usually keeps working; bundlers reintroduce the same problem when they cannot see a dynamic path."),
                new("clr-why", "explanation", "Why does the runtime use tiered compilation instead of always using the optimising JIT? What does the strategy cost, and when does the trade-off matter?", "", [], "", "Quickly-jitted tier-0 code keeps startup fast and avoids spending compile time on methods that run once. The runtime then re-jits hot methods with full optimisation, using dynamic PGO profiles collected from tier-0. The costs are extra memory for multiple code versions, background compilation work, and a warm-up period during which the app runs slower. The trade-off matters most for short-lived processes (where warm-up is a large fraction of the work) and for latency-sensitive services that receive a burst immediately after start.", "Name both sides of the trade-off: startup latency, steady-state throughput and memory.", "Like V8's baseline and optimising tiers. Node services show the same cold-start versus steady-state difference."),
            ]),

        new Module(
            "gc",
            "Memory Allocation and Garbage Collection",
            "Understand why allocation is cheap, when the Large Object Heap bites, and why a long-lived service leaks memory even with a garbage collector.",
            "Reason about reachability, generations, the Large Object Heap and GC modes, and recognise the classic managed memory leak.",
            22,
            "V8 also uses a generational, compacting collector, so the idea is familiar. The difference is control. .NET lets you pick workstation or server GC, tune it and read GC counters, and it has a separate Large Object Heap that is not compacted by default. In Node you rarely tune GC from application code; in a .NET service you sometimes have to.",
            "CLR via C#, 4th Edition - Chapter 21, \"The Managed Heap and Garbage Collection\" (sections \"Managed Heap Basics\", \"The Garbage Collection Algorithm\", \"Generations: Improving Performance\", \"Large Objects\", \"Garbage Collection Modes\").",
            [
                new("Fundamentals of garbage collection", "https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/fundamentals"),
                new("Garbage collection", "https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/gc"),
                new("The Large Object Heap", "https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/large-object-heap"),
                new("Workstation and server GC", "https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/workstation-server-gc"),
                new("Background GC", "https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/background-gc"),
                new("Dynamic adaptation to application sizes (DATAS)", "https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/datas"),
                new("Garbage collector config settings", "https://learn.microsoft.com/en-us/dotnet/core/runtime-config/garbage-collector")
            ],
            [
                new("Allocation and what 'collectable' means", 7, "Allocating in .NET is cheap: the runtime bumps a pointer in a thread-local area. That works because the GC owns the heap and can move objects. To find garbage, the GC walks the roots (static fields, thread stacks, CPU registers, GC handles), marks everything reachable, and compacts the rest. An object is collected only when nothing reachable points at it. A local variable going out of scope frees nothing on its own.", "static readonly List<Order> Recent = new();  // a root\n\nvoid Handle(Order order) {\n  Recent.Add(order);   // now reachable for the process lifetime\n}"),
                new("Generations and the Large Object Heap", 7, "Most objects die young, so the heap has three generations. Gen0 is small and collected often and cheaply. Survivors move to gen1 and then gen2. Anything 85,000 bytes or larger goes to the Large Object Heap, which is collected with gen2 and is not compacted by default. Allocating large buffers in a loop causes frequent gen2 collections and can fragment the heap. Pool them instead.", "for (var i = 0; i < 1000; i++) {\n  var buffer = new byte[100_000];  // 100 KB -> Large Object Heap\n  await ProcessAsync(buffer);\n}\n\n// Better: reuse a pooled buffer\nvar rented = ArrayPool<byte>.Shared.Rent(100_000);"),
                new("GC modes, DATAS and tuning", 6, "Workstation GC keeps pauses short for client apps. Server GC creates a heap and a GC thread per core for throughput. Since .NET 9, server GC uses DATAS by default: it sizes the heap relative to live data instead of growing aggressively, which helps container memory limits. Background GC collects gen2 without stopping everything for as long. GC.Collect forces a full blocking collection and is almost always the wrong tool.", "// .NET 9+ server GC uses DATAS by default\nGC.GetTotalMemory(forceFullCollection: false);  // observe, do not force")
            ],
            "Generational, compacting, mark-and-sweep collection is still how .NET works. Gen0/1/2, the 85,000-byte Large Object Heap threshold, workstation and server GC, background GC and finalisation all still apply. DATAS has been the default server GC mode since .NET 9, so containerised services get a heap that tracks live data. Use EventPipe and dotnet-counters to watch it.",
            "Early .NET Framework GC had no background GC (it arrived in .NET 4.5) and no DATAS. Tuning meant app.config settings and machine-wide CLR behaviour. The GAC and AppDomains are gone. Old advice to call GC.Collect after a big operation is not right for modern services.",
            "Read sections 1 and 2 and answer the allocation and Large Object Heap questions (about 9 minutes). Tuning and DATAS can wait.",
            "reachability and GC roots, generations, Large Object Heap allocation, GC modes and DATAS, and managed memory leaks from caches and event handlers. Use background workers and API services.",
            [
                new("gc-collect", "multiple-choice", "When is an object eligible for garbage collection?", "static readonly List<Order> Recent = new();", ["When it is no longer reachable from any GC root", "When the variable that referenced it goes out of scope", "When you call GC.Collect"], "When it is no longer reachable from any GC root", "The GC collects unreachable objects. A local going out of scope does not make an object unreachable if something else still references it - for example a static list, an event handler or a cache. GC.Collect can force a collection, but it does not change what is reachable.", "Separate the variable from the object and ask what still points at the object.", "V8's mark-and-sweep uses the same reachability idea; a closure or module-level reference keeps an object alive in Node too."),
                new("gc-loh", "prediction", "This loop runs in a background worker. What is the likely memory impact?", "for (var i = 0; i < 1000; i++) {\n  var buffer = new byte[100_000];\n  await ProcessAsync(buffer);\n}", ["Each 100 KB array goes to the Large Object Heap, so gen2 collections and fragmentation are likely", "Each array is gen0 and costs almost nothing", "The arrays are allocated on the stack"], "Each 100 KB array goes to the Large Object Heap, so gen2 collections and fragmentation are likely", "100,000 bytes exceeds the 85,000-byte Large Object Heap threshold. Large objects are collected with gen2 and are not compacted by default, so allocating them in a loop creates frequent gen2 pressure and can fragment the heap. Reuse buffers with ArrayPool<byte>.Shared or a pooled stream instead.", "Compare the allocation size with the Large Object Heap threshold, then ask how often the loop runs.", "Node's Buffer.allocUnsafe also benefits from pooling; the difference is that .NET exposes the pool and the heap behaviour directly."),
                new("gc-leak", "bug", "An AI assistant called this a cache for a long-running worker. It passes tests. What is the production risk?", "static readonly Dictionary<string, byte[]> Cache = new();\npublic byte[] Get(string key) {\n  if (!Cache.TryGetValue(key, out var value))\n    Cache[key] = value = Load(key);\n  return value;\n}", ["Unbounded growth: entries stay reachable forever, so the process leaks until it runs out of memory", "The dictionary is not thread-safe, so it always corrupts immediately", "byte[] cannot be stored in a dictionary"], "Unbounded growth: entries stay reachable forever, so the process leaks until it runs out of memory", "A static dictionary is a GC root, so every entry stays reachable for the life of the process. With unbounded keys the heap grows until the container is killed. A real cache needs a size or time limit (for example IMemoryCache with a size limit), and concurrent access needs a ConcurrentDictionary or locking.", "Ask what keeps each entry reachable and what bounds the number of keys.", "A module-level Map in Node has exactly the same leak. The GC only helps with objects nothing references."),
                new("gc-generations", "explanation", "Why does the GC use generations, and how does reachability decide whether an object is collected? Explain why calling GC.Collect in a service is usually a bad idea.", "", [], "", "The generational hypothesis says most objects die young. Gen0 is small and collected frequently and cheaply; survivors are promoted to gen1 and gen2, which are collected less often. This lets the GC do most of its work on a small region. An object is collected only when it is unreachable from a GC root; scope is irrelevant. GC.Collect forces a full blocking collection across all generations, which pauses the app, promotes objects prematurely and defeats the collector's tuning, so it should be reserved for diagnostics or very specific scenarios.", "Explain both the performance idea (cheap young collections) and the correctness idea (reachability).", "V8 also uses a young generation and an old generation. Node exposes far less control, so the same reasoning shows up as 'avoid retaining references'."),
            ]),

        new Module(
            "dispose",
            "IDisposable, Finalizers and Resource Management",
            "Learn deterministic cleanup, why finalizers are a safety net rather than a plan, and how DI scopes decide when a service is disposed.",
            "Choose between using, IAsyncDisposable and finalizers, and reason about resource lifetimes in an ASP.NET Core service.",
            21,
            "Node has no IDisposable. You clean up with try/finally, a library close() method, or the newer using and Symbol.dispose syntax. If you forget, the file or socket stays open until the process ends. C# gives you deterministic Dispose plus a finalizer as a safety net, but Dispose is the path to design for.",
            "CLR via C#, 4th Edition - Chapter 21, \"The Managed Heap and Garbage Collection\" (sections \"Working with Types Requiring Special Cleanup\", \"Finalization Internals\", \"Monitoring and Controlling the Lifetime of Objects Manually\").",
            [
                new("Implement a Dispose method", "https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/implementing-dispose"),
                new("Cleaning up unmanaged resources", "https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/unmanaged"),
                new("IDisposable", "https://learn.microsoft.com/en-us/dotnet/api/system.idisposable"),
                new("IAsyncDisposable", "https://learn.microsoft.com/en-us/dotnet/api/system.iasyncdisposable"),
                new("using statement", "https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/statements/using"),
                new("CA2000: Dispose objects before losing scope", "https://learn.microsoft.com/en-us/dotnet/fundamentals/code-analysis/quality-rules/ca2000")
            ],
            [
                new("Dispose and using", 7, "The GC frees managed memory, but it knows nothing about files, sockets, database connections or native buffers. IDisposable.Dispose releases those at a point you choose. using (or await using for IAsyncDisposable) calls Dispose in a finally, so it runs even when an exception is thrown. FileStream, DbConnection, HttpResponseMessage and SemaphoreSlim all implement it.", "using var stream = File.OpenRead(\"orders.csv\");\nusing var reader = new StreamReader(stream);\nvar text = await reader.ReadToEndAsync();\n// both are disposed when the method exits, even on exception"),
                new("Finalizers and SafeHandle", 7, "A finalizer is a safety net for a type that owns an unmanaged resource and was never disposed. It is expensive: the object survives an extra collection, waits in a queue, and is finalised on a shared thread at an unpredictable time. The usual pattern is Dispose(bool disposing) with GC.SuppressFinalize(this). Better still, wrap the raw handle in SafeHandle and let the framework write the finalizer. Never touch other managed objects from a finalizer.", "sealed class LogWriter : IDisposable {\n  readonly SafeFileHandle handle;   // SafeHandle owns the native handle\n  public LogWriter(SafeFileHandle handle) => this.handle = handle;\n  public void Dispose() => handle.Dispose();\n}"),
                new("Who disposes what in a service", 6, "In ASP.NET Core the DI container disposes what it created: scoped services at the end of a request, singletons at shutdown. If you resolve a scoped service from the root provider, it lives until shutdown and is never disposed. IHttpClientFactory manages handler lifetimes, so do not dispose an HttpClient that was injected into you. A BackgroundService gets StopAsync and disposal when the host shuts down.", "public sealed class PriceClient(HttpClient http) {  // owned by DI\n  public Task<string> GetAsync(string sku) =>\n    http.GetStringAsync($\"/prices/{sku}\");          // do not dispose http\n}\n\nbuilder.Services.AddHostedService<SyncWorker>();     // disposed at shutdown")
            ],
            "IDisposable, IAsyncDisposable, using and await using, the Dispose(bool) pattern, GC.SuppressFinalize and SafeHandle are all current on .NET 10. DI disposal, IHttpClientFactory and BackgroundService lifetimes behave as described here. Analyzers such as CA2000 flag many missed disposals.",
            "On .NET Framework, SafeHandle competed with CriticalFinalizerObject and constrained execution regions (CERs); CERs are no longer a mainstream tool. Close() as an alias for Dispose() on Stream and similar types is legacy. ServicePointManager and HttpWebRequest are replaced by HttpClient and SocketsHttpHandler. Do not add [Serializable] for BinaryFormatter persistence; BinaryFormatter is removed in modern .NET.",
            "Read section 1 and answer the using and disposal questions (about 8 minutes). Finalisation internals and service lifetimes are a second sitting.",
            "IDisposable and IAsyncDisposable, using and await using, the dispose pattern, finalizers and SafeHandle, and DI scopes, HttpClient and background-worker lifetimes.",
            [
                new("dispose-when", "multiple-choice", "When does using call Dispose?", "using var stream = File.OpenRead(\"orders.csv\");", ["At the end of the block, even if an exception is thrown", "When the object is next garbage collected", "Only if you call GC.Collect"], "At the end of the block, even if an exception is thrown", "using is compiled into try/finally, so Dispose runs when control leaves the block, including on an exception. That determinism is the point: the file handle is released immediately rather than at some future collection.", "Think about what the compiler emits for using.", "Node's newer using syntax and Symbol.dispose follow the same idea; manual try/finally is the older equivalent."),
                new("dispose-return", "prediction", "What is disposed, and when, in this method?", "static async Task<int> ReadAsync(string path) {\n  using var stream = File.OpenRead(path);\n  using var reader = new StreamReader(stream);\n  var text = await reader.ReadToEndAsync();\n  return text.Length;\n}", ["Both reader and stream are disposed when the method returns, including on exception", "Only the reader is disposed; the stream is left open", "Neither is disposed because the method returns a value"], "Both reader and stream are disposed when the method returns, including on exception", "using declarations are disposed at the end of the enclosing scope, in reverse order of declaration, and the compiler emits the cleanup so that it also runs when the method throws or returns. The reader is disposed first, which flushes and closes the stream it wraps, then the stream itself.", "List the using declarations in order and reverse it for disposal order.", "There is no automatic equivalent in Node unless you use explicit using/Symbol.dispose; a forgotten close leaks the descriptor."),
                new("dispose-shared", "bug", "An AI assistant wrote this client and disposes the injected HttpClient inside the method. Why is that a bug?", "public sealed class PriceClient(HttpClient http) {\n  public async Task<decimal> GetAsync(string sku) {\n    using (http) {\n      var json = await http.GetStringAsync($\"/prices/{sku}\");\n      return JsonSerializer.Deserialize<decimal>(json);\n    }\n  }\n}", ["The client is owned by the caller or DI; disposing it here breaks every later call that reuses it", "HttpClient is not IDisposable, so the code does not compile", "using cannot be combined with await"], "The client is owned by the caller or DI; disposing it here breaks every later call that reuses it", "An injected dependency is owned by the container or caller, not by the method. Disposing it cancels in-flight requests and makes later calls throw ObjectDisposedException. Create and dispose your own HttpClient when you own it; when it comes from DI, let the container manage its lifetime.", "Ask who created the object and who is responsible for ending its life.", "Disposing an injected Angular HttpClient would be equally wrong; the injector owns it."),
                new("dispose-why", "explanation", "Why does .NET need both Dispose and finalizers? Explain what finalisation costs, why SafeHandle is preferred, and how DI scopes decide when a service is disposed.", "", [], "", "Dispose gives deterministic cleanup at a known point, which is what you want for files, sockets and connections. A finalizer is a fallback for the case where Dispose was never called: the GC notices the object is unreachable, keeps it alive, queues it for finalisation on a dedicated thread, and only reclaims it on a later collection. That costs an extra collection and delays release, and the finalizer thread is shared, so blocking it is dangerous. SafeHandle wraps the raw handle, guarantees release even during shutdown, and avoids most hand-written finalizers. In DI, the container disposes what it created: scoped instances at the end of the scope, singletons at container shutdown; resolving a scoped service from the root provider turns it into an undeclared singleton that is never disposed.", "Cover determinism, the cost of finalisation, and DI ownership in that order.", "Node has no finalizer safety net, so leaks are silent. C# lets you design deterministic cleanup and still survive mistakes."),
            ]),

        new Module(
            "async",
            "Tasks, async/await and Threading",
            "See async/await as a state machine, understand when a thread is released, and avoid the concurrency bugs AI code reproduces most often.",
            "Explain what await does to a thread, choose between async I/O and Task.Run, and recognise async void and sync-over-async bugs.",
            23,
            "JavaScript's async/await and Promises are the closest match. await suspends the function, not the thread, and Node runs everything on one thread with an event loop. C# also has a real thread pool, so it can run CPU work in parallel. That is why Task.Run exists in C# and has no direct Promise equivalent. Node's AbortController maps closely to CancellationToken.",
            "CLR via C#, 4th Edition - Chapter 26, \"Thread Basics\"; Chapter 27, \"Compute-Bound Asynchronous Operations\"; Chapter 28, \"I/O-Bound Asynchronous Operations\" (sections \"C#'s Asynchronous Functions\", \"How the Compiler Transforms an Async Function into a State Machine\").",
            [
                new("Asynchronous programming with async and await", "https://learn.microsoft.com/en-us/dotnet/csharp/asynchronous-programming/"),
                new("Task-based asynchronous pattern (TAP)", "https://learn.microsoft.com/en-us/dotnet/standard/asynchronous-programming-patterns/task-based-asynchronous-pattern-tap"),
                new("Consuming the task-based asynchronous pattern", "https://learn.microsoft.com/en-us/dotnet/standard/asynchronous-programming-patterns/consuming-the-task-based-asynchronous-pattern"),
                new("Managed threading basics", "https://learn.microsoft.com/en-us/dotnet/standard/threading/managed-threading-basics"),
                new("Threading objects and features", "https://learn.microsoft.com/en-us/dotnet/standard/threading/threading-objects-and-features"),
                new("Overview of synchronization primitives", "https://learn.microsoft.com/en-us/dotnet/standard/threading/overview-of-synchronization-primitives")
            ],
            [
                new("Tasks, threads and the thread pool", 7, "A Task is a promise of a future result, not a thread. CPU-bound work runs on thread-pool threads. I/O-bound work uses the operating system's async I/O and holds no thread while it waits. The thread pool grows slowly, so blocking a pool thread with .Result or Thread.Sleep takes capacity away from everyone else. Use ValueTask when a result is often ready immediately and you await it once.", "var html = await http.GetStringAsync(url);   // I/O: no thread held\nvar hash = await Task.Run(() => Compute(data));  // CPU: uses a pool thread"),
                new("What await really does", 7, "The compiler rewrites an async method into a state machine. At each await, if the operation has not finished, the method saves its state, registers a continuation and returns its Task to the caller. The thread is released. When the operation completes, the continuation runs. async void is only for event handlers: there is no Task to await, so an exception goes to the synchronization context and can crash the process. ASP.NET Core has no synchronization context, so ConfigureAwait(false) matters mainly in libraries.", "async Task<int> LoadAsync() {\n  var text = await reader.ReadToEndAsync();  // may release the thread\n  return text.Length;\n}\n\nasync void FireAndForget() {   // avoid: no Task, exception escapes\n  await Task.Delay(100);\n  throw new InvalidOperationException(\"boom\");\n}"),
                new("Concurrency and cancellation", 6, "await does not make code thread-safe. Two continuations can interleave around shared state, and Dictionary is not safe for concurrent writes. Use ConcurrentDictionary, SemaphoreSlim or a lock, and never lock across an await. Pass a CancellationToken through async APIs and check it. Task.WhenAll reports the first exception and keeps the rest on the task.", "using var gate = new SemaphoreSlim(10);  // throttle async work\nawait gate.WaitAsync(ct);\ntry { await http.GetAsync(url, ct); }\nfinally { gate.Release(); }\n\nawait Task.WhenAll(tasks);")
            ],
            "Tasks, async/await, CancellationToken, IAsyncEnumerable<T>, ValueTask, SemaphoreSlim and the thread pool are the current model on .NET 10. ConfigureAwait(false) matters in libraries, not in ASP.NET Core application code, because there is no synchronization context. Task.Run is for CPU-bound work only. The programming model is unchanged.",
            "Thread.Abort is not supported on modern .NET; use cancellation instead. Task.Factory.StartNew with custom schedulers has largely given way to Task.Run. The .NET Framework SynchronizationContext deadlocks (.Result in ASP.NET or UI code) are less common in ASP.NET Core but still appear in desktop and older code. Keep async void for event handlers only.",
            "Read sections 1 and 2 and answer the await and async void questions (about 9 minutes). Concurrency and cancellation are the second sitting.",
            "await and the state machine, thread-pool starvation, async void, sync-over-async, Task.Run for CPU-bound work, cancellation and concurrency hazards in services and background workers.",
            [
                new("async-await", "multiple-choice", "What does await do when the awaited operation has not completed?", "var response = await httpClient.GetAsync(url);", ["Registers a continuation and returns control to the caller, releasing the thread", "Blocks the current thread until the operation finishes", "Starts a new OS thread for the continuation"], "Registers a continuation and returns control to the caller, releasing the thread", "await suspends the async method, not the thread. The method returns an incomplete Task to its caller; when the awaited operation completes, the continuation is scheduled and the method resumes. No thread is held while the I/O is in flight, which is why async scales better than blocking.", "Ask who is doing the waiting while the operation is pending.", "This is exactly how JavaScript await suspends an async function and returns a Promise."),
                new("async-void", "prediction", "What happens to the exception thrown in this async void method?", "public void Start() { FireAndForget(); }\nasync void FireAndForget() {\n  await Task.Delay(100);\n  throw new InvalidOperationException(\"boom\");\n}", ["It is raised on the captured synchronization context or as an unhandled exception, potentially crashing the process", "It is stored in a Task the caller can await", "It is silently swallowed"], "It is raised on the captured synchronization context or as an unhandled exception, potentially crashing the process", "An async void method has no Task to observe. When it throws after an await, the exception is posted to the SynchronizationContext that was current when the method started; if there is none, it becomes an unhandled exception. Use async Task so callers can await and handle failures.", "Where would the exception go if there is no Task to await?", "A rejected Promise with no catch handler is the closest Node analogue: an unhandled rejection."),
                new("async-result", "bug", "An AI assistant generated this controller using .Result. Why is that a problem?", "public IActionResult Get(int id) {\n  var order = _orders.FindAsync(id).Result;\n  return Ok(order);\n}", ["It blocks a thread-pool thread, risking thread-pool starvation and deadlock", "It always throws AggregateException", "async methods cannot return Task<T>"], "It blocks a thread-pool thread, risking thread-pool starvation and deadlock", ".Result blocks the calling thread while the operation completes. Under load this consumes pool threads that could be serving other requests, and in a context with a SynchronizationContext it can deadlock. Make the method async and await the task: async Task<IActionResult> Get(int id) { var order = await _orders.FindAsync(id); return Ok(order); }.", "Count how many threads are busy while the database call is in flight.", "In Node, blocking the event loop with a synchronous call has a similar effect, but there is only one thread to lose."),
                new("async-why", "explanation", "Explain why asynchronous I/O does not need a thread while it waits, why async void is dangerous, and when Task.Run is the right tool versus a mistake.", "", [], "", "For I/O, the runtime starts an OS operation and registers a continuation; no managed thread is consumed while the device works, so a small pool can serve many requests. Task.Run moves CPU-bound work onto a pool thread, which is useful for parallelism but pointless for I/O because it just occupies a thread while waiting. async void is dangerous because the caller cannot await it and exceptions escape to the synchronization context or the process; it belongs only in event handlers. Use async Task everywhere else, and Task.Run only for genuinely CPU-bound work that should not block the caller.", "Separate I/O-bound from CPU-bound, then say who waits in each case.", "Promise and Task.Run have no direct equivalent; Node's single thread means Task.Run-like parallelism is explicit (worker_threads)."),
            ]),

        new Module(
            "generics",
            "Generics and Runtime Behaviour",
            "Understand reified generics, why value-type instantiations avoid boxing, and how constraints shape what the JIT can do.",
            "Explain the difference between erased and reified generics, choose constraints deliberately, and recognise generic-equality bugs.",
            20,
            "TypeScript generics are erased. Box<number> and Box<string> are the same JavaScript object at run time, so you cannot ask a generic for its type argument. C# generics are reified: the type argument is stored in metadata, so List<int> and List<string> are different types and reflection can see them.",
            "CLR via C#, 4th Edition - Chapter 12, \"Generics\" (sections \"Generics Infrastructure\", \"Open and Closed Types\", \"Code Explosion\", \"Verifiability and Constraints\").",
            [
                new("Generic type parameters (C# programming guide)", "https://learn.microsoft.com/en-us/dotnet/csharp/programming-guide/generics/"),
                new("Generics in .NET", "https://learn.microsoft.com/en-us/dotnet/standard/generics/"),
                new("Performance-focused C# (Span<T> and friends)", "https://learn.microsoft.com/en-us/dotnet/csharp/advanced-topics/performance/")
            ],
            [
                new("Reified generics", 7, "In C#, List<int> and List<string> are real types, and the runtime knows the type arguments. For value types, the JIT compiles specialised code, so List<int> is backed by a real int[] with no boxing. For reference types, instantiations such as List<string> and List<object> share the same code. In TypeScript the type arguments are erased at compile time and do not exist at run time.", "var numbers = new List<int> { 1, 2, 3 };   // int[], no boxing\nvar names = new List<string> { \"Ada\" };    // shares code with List<object>\n\nConsole.WriteLine(typeof(List<int>).GetGenericArguments()[0]);  // System.Int32"),
                new("Constraints and default(T)", 7, "Constraints (where T : class, struct, new(), an interface, and so on) are checked by the compiler and stored in metadata. They let the JIT call members directly instead of boxing or reflecting. default(T) is null for reference types and the zero value for value types. An unconstrained T cannot be compared to null without a constraint. Static abstract interface members (C# 11) allow generic maths.", "static T Get<T>(T[] items, int index) =>\n  index < items.Length ? items[index] : default!;\n\nConsole.WriteLine(Get(new[] { 1, 2 }, 5));        // 0\nConsole.WriteLine(Get(new[] { \"a\" }, 5) is null); // True"),
                new("Generic APIs and equality", 6, "Generic collections avoid boxing and give compile-time safety. Span<T> and Memory<T> let you slice without copying. Equality is a common trap: Dictionary<TKey, TValue> uses EqualityComparer<TKey>.Default, which calls Equals and GetHashCode. If your key type overrides neither, you get reference equality and lookups fail. Records generate value equality for you.", "public record Sku(string Code);   // records give value equality\n\nvar prices = new Dictionary<Sku, decimal>();\nprices[new Sku(\"ABC\")] = 9.99m;\nprices.TryGetValue(new Sku(\"ABC\"), out var price);")
            ],
            "Reified generics, JIT specialisation for value types, constraints, covariance and contravariance, EqualityComparer<T>.Default and generic collections are unchanged on .NET 10. Static abstract interface members and generic math (C# 11, .NET 7) are current. Span<T> and Memory<T> are central to modern allocation-free APIs.",
            "Reified generics arrived with .NET Framework 2.0 and have not changed. The non-generic System.Collections types are legacy, and using ArrayList or Hashtable for mixed types boxes value types. Nothing about generics was removed in the move to .NET Core; more of the framework is generic now.",
            "Read section 1 and answer the reified/erased and default(T) questions (about 8 minutes). Constraints and generic APIs can wait.",
            "reified versus erased generics, JIT specialisation, boxing avoidance, constraints, default(T), generic equality via EqualityComparer<T>.Default, and code explosion.",
            [
                new("generics-erasure", "multiple-choice", "What is true of List<int> on .NET 10?", "var numbers = new List<int> { 1, 2, 3 };", ["The runtime knows the type argument and stores real int values without boxing", "Type arguments are erased, so every element is boxed to object", "List<int> does not compile"], "The runtime knows the type argument and stores real int values without boxing", "C# generics are reified: the type argument is part of the type's identity and is stored in metadata. List<int> is backed by an int[], so no boxing occurs. This is a real difference from TypeScript, where generics are erased and Box<number> is the same run-time object as Box<string>.", "Ask what the runtime knows about the element type.", "TypeScript erases type parameters; C# keeps them, which is why reflection can see them."),
                new("generics-default", "prediction", "What does this program print?", "static T Get<T>(T[] items, int index) => index < items.Length ? items[index] : default!;\nConsole.WriteLine(Get(new[] { 1, 2 }, 5));\nConsole.WriteLine(Get(new[] { \"a\" }, 5) is null);", ["0 then True: default(int) is 0 and default(string) is null", "It throws IndexOutOfRangeException", "It does not compile"], "0 then True: default(int) is 0 and default(string) is null", "default(T) is the zero value for a value type and null for a reference type. The method returns 0 for int and null for string, so the second line prints True. This is why generic APIs often need a constraint or a nullable annotation to express intent clearly.", "Work out default(T) for both instantiations.", "TypeScript would return undefined; C# has no undefined and uses default(T) instead."),
                new("generics-equality", "bug", "An AI assistant generated this lookup and expected it to return true. Why does it return false?", "public sealed class Sku {\n  public Sku(string code) => Code = code;\n  public string Code { get; }\n}\nvar prices = new Dictionary<Sku, decimal>();\nprices[new Sku(\"ABC\")] = 9.99m;\nvar found = prices.TryGetValue(new Sku(\"ABC\"), out var price);", ["Sku uses reference equality, so the second instance is a different key", "Dictionary compares properties automatically", "It does not compile because Sku has no parameterless constructor"], "Sku uses reference equality, so the second instance is a different key", "Dictionary<TKey, TValue> uses EqualityComparer<TKey>.Default, which calls Equals and GetHashCode. Sku overrides neither, so it inherits reference equality and the two instances are different keys. Implement value equality (or use a record, which generates it) when a class is used as a dictionary key.", "Ask what EqualityComparer<TKey>.Default uses for this type.", "TypeScript Map keys use SameValueZero, so two structurally equal objects are still different keys - the same trap."),
                new("generics-why", "explanation", "Explain what reified generics means, why value-type instantiations avoid boxing, and what code explosion is. When would you choose a constraint over object?", "", [], "", "Reified generics keep the type argument in metadata, so List<int> and List<string> are distinct run-time types and the runtime can generate specialised code. For value types this means an int[] backing store rather than an object[] of boxes, which removes per-element allocation and lets the JIT call members directly. Code explosion is the cost: each distinct value-type instantiation may get its own native code, so many instantiations increase memory and JIT time; reference-type instantiations share code. A constraint such as where T : IComparable<T> is preferable to object because it preserves type safety, avoids casts and boxing, and lets the JIT generate direct calls.", "Cover the run-time knowledge, the boxing difference and the cost.", "TypeScript's erased generics have no code explosion because there is no specialised code - the trade-off is no run-time type information."),
            ]),

        new Module(
            "exceptions",
            "Exceptions and Error Handling",
            "Distinguish throwing, catching and rethrowing, and design error handling that a service can actually reason about.",
            "Preserve stack traces, use filters deliberately, and decide when a failure should throw rather than return a result.",
            20,
            "JavaScript's try/catch/finally looks similar, and both languages use exceptions for exceptional cases. C# adds exception filters (when), which JavaScript does not have. C#'s using and await using are deterministic cleanup that JavaScript only approximates with using and Symbol.dispose.",
            "CLR via C#, 4th Edition - Chapter 20, \"Exceptions and State Management\" (sections \"Exception-Handling Mechanics\", \"Guidelines and Best Practices\", \"Exception-Handling Performance Considerations\").",
            [
                new("Exceptions and exception handling (C#)", "https://learn.microsoft.com/en-us/dotnet/csharp/fundamentals/exceptions/"),
                new("Best practices for exceptions", "https://learn.microsoft.com/en-us/dotnet/standard/exceptions/best-practices-for-exceptions")
            ],
            [
                new("try, catch, finally and filters", 7, "try/catch/finally works as you expect. catch clauses are tried in order, and a when condition is checked before the stack unwinds, so a filter that returns false lets the runtime keep looking without the cost of unwinding. finally runs on both the normal and exceptional paths. Use throw; to rethrow and keep the original stack trace. throw ex; restarts the trace at the rethrow, so your logs point at the wrong line.", "try {\n  await client.SendAsync(request);\n}\ncatch (HttpRequestException ex) when (ex.StatusCode == HttpStatusCode.ServiceUnavailable) {\n  await Task.Delay(500);\n  throw;   // keeps the original stack trace\n}"),
                new("Cost, stack traces and task exceptions", 7, "Throwing is expensive: the runtime captures a stack trace and walks handlers. Do not use exceptions for normal control flow on a hot path. When you must rethrow across a boundary, ExceptionDispatchInfo.Capture(ex).Throw() preserves the original trace. Task-returning methods surface exceptions when you await them. OperationCanceledException should normally be propagated, not logged as a failure.", "try { await work; }\ncatch (OperationCanceledException) { throw; }      // cancellation is not an error\ncatch (Exception ex) {\n  logger.LogError(ex, \"work failed\");\n  throw;\n}"),
                new("Designing error handling", 6, "Catch only what you can handle or translate. Log and rethrow, or wrap the original as InnerException. Do not catch Exception and return a default value: that hides cancellation, timeouts and bugs behind a plausible result. Validate input with explicit checks when failure is expected. Let ASP.NET Core's exception handler map known exceptions to status codes.", "public async Task<Order?> FindAsync(int id, CancellationToken ct) {\n  var order = await repo.FindAsync(id, ct);  // cancellation flows through\n  return order;                              // a missing order is a null result\n}")
            ],
            "try/catch/finally, exception filters, throw;, ExceptionDispatchInfo, AggregateException and OperationCanceledException handling are current on .NET 10. ASP.NET Core's exception-handler middleware and ProblemDetails are the modern way to map exceptions to responses. Filters remain the cheapest way to decline a catch.",
            "ThreadAbortException and AppDomain.UnhandledException are .NET Framework/Windows-only; Thread.Abort throws PlatformNotSupportedException. [Serializable] and binary serialization of exceptions are gone from modern .NET. Exception cost was already significant in .NET Framework; what changed is the tooling (filters, ExceptionDispatchInfo) and the guidance against catch-all handlers.",
            "Read sections 1 and 2 and answer the rethrow and finally questions (about 9 minutes). Service-level design is a second sitting.",
            "throw versus throw ex, finally semantics, exception filters, exception cost, swallowing and translation, cancellation exceptions, and service error-handling design.",
            [
                new("exceptions-rethrow", "multiple-choice", "What is the difference between throw; and throw ex;?", "try { await _client.SendAsync(request); }\ncatch (HttpRequestException ex) {\n  _logger.LogError(ex, \"send failed\");\n  throw;\n}", ["throw; preserves the original stack trace; throw ex; resets it", "They are identical because the runtime keeps the original trace", "throw; is only allowed inside finally"], "throw; preserves the original stack trace; throw ex; resets it", "throw; rethrows the exception currently being handled without changing its stack trace. throw ex; throws the same object again but the runtime records the new throw site, so the trace no longer shows where the failure originated. Always prefer throw; when you want the original diagnosis.", "Look at what the runtime records at the throw site.", "JavaScript has no equivalent distinction; rethrowing with throw preserves the original error in V8."),
                new("exceptions-finally", "prediction", "What does this program print?", "static int Run() {\n  try { return 1; }\n  finally { Console.WriteLine(\"finally\"); }\n}\nConsole.WriteLine(Run());", ["finally then 1", "1 then finally", "finally then 0"], "finally then 1", "finally runs before the method actually returns, so the message is printed first and then the return value is produced. The same ordering holds when an exception propagates: cleanup runs before control leaves the method.", "Decide when the return value is produced relative to leaving the try block.", "JavaScript's finally behaves the same way; a return inside finally would override the try return in both languages."),
                new("exceptions-swallow", "bug", "An AI assistant wrote this catch-all and claimed it makes the service resilient. Why is it dangerous?", "public async Task<Order?> GetAsync(int id) {\n  try { return await _repo.FindAsync(id); }\n  catch (Exception) { return null; }\n}", ["It hides cancellation, timeouts and bugs as 'not found', so callers cannot distinguish a missing order from a broken database", "catch (Exception) does not compile", "It breaks the async state machine"], "It hides cancellation, timeouts and bugs as 'not found', so callers cannot distinguish a missing order from a broken database", "A missing order is a legitimate null result; a cancelled request, a timeout or a database failure are not. Swallowing everything turns them all into null, so retries, alerts and status codes are wrong and the original stack trace is lost. Catch only the specific exception you can handle, or translate it deliberately and preserve the inner exception.", "List the different failures this single catch block collapses into one result.", "A bare catch in Node does the same thing; it turns programming errors into plausible-looking results."),
                new("exceptions-why", "explanation", "Explain why throw ex; is harmful, why exception filters are useful, and how you would decide between returning a result type and throwing for an expected failure.", "", [], "", "throw ex; discards the original stack trace, so the log points at the rethrow rather than the cause; throw; preserves it. Exception filters run before unwinding, so a when clause that returns false declines the catch without the cost of a stack unwind, which is useful for deciding based on exception state or logging. Use a result type when failure is expected and part of normal control flow - validation, 'not found', a failed lookup - because exceptions are expensive and make the common path exceptional. Throw when the caller cannot reasonably continue, when the failure is a bug, or when an invariant is broken; document the exceptions a public API can throw.", "Cover stack traces, the cost model and the expected-versus-exceptional boundary.", "Node's error-first callbacks are a result type in disguise; Promise rejections behave like exceptions."),
            ]),

        new Module(
            "reflection",
            "Reflection, Attributes and Metadata",
            "Learn what metadata the runtime keeps, why attributes are inert, and how trimming and AOT change reflection-based designs.",
            "Explain how attributes are read, why reflection is slow, and choose between reflection, compiled delegates and source generators.",
